{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "Medium",
      "file": "TaskSearchController.cls",
      "lines": "findTasksBySubject",
      "explanation": "The method concatenates user input into a dynamic SOQL query string, which can lead to SOQL injection.",
      "remediation": "Use bind variables or Database.queryWithBinds to safely include user input in SOQL queries."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "Medium",
      "file": "AccountSearchController.cls",
      "lines": "searchAccounts",
      "explanation": "The searchKey parameter is concatenated directly into the SOQL query string, which can lead to SOQL injection.",
      "remediation": "Use bind variables or String.escapeSingleQuotes to safely include user input in SOQL queries."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS Violation",
      "severity": "Medium",
      "file": "AccountSearchController.cls",
      "lines": "searchAccounts",
      "explanation": "The query does not enforce field-level security (FLS) checks, which could allow users to access fields they do not have permission to view.",
      "remediation": "Use WITH SECURITY_ENFORCED in the SOQL query to enforce FLS checks."
    }
  ]
}

